WITH gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS session_start_flag FROM transactions), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT id, txn_type, amount, txn_time, is_flagged, burst_id, CASE WHEN txn_type RLIKE '^(CREDIT|DEBIT)$' THEN 'OTHER_ZONE' ELSE 'EXTENDED' END AS txn_type_zone FROM sessionized;
